      endpoint: req.path,
      method: req.method,
      statusCode: res.statusCode,
      ip,
      userId: req.user?.id ?? req.apiKeyUser?.id ?? null,
      apiKeyId: req.apiKey?.id ?? null,
      responseTime: duration3
