async function checkIpBlock(req, res, next) {
  const ip = (req.ip || req.socket?.remoteAddress || "").replace("::ffff:", "");
  if (!ip) {
    next();
    return;
  }
  const cacheKey = `ip_blocked:${ip}`;
  let isBlocked = get(cacheKey);
  if (isBlocked === null) {
    const block = await db.query.ipBlocks.findFirst({
      where: eq(ipBlocks.ip, ip)
    }).catch(() => null);
    isBlocked = !!block;
    set2(cacheKey, isBlocked, 60);
  }
  if (isBlocked) {
    res.status(403).json({ error: "Your IP address has been blocked." });
    return;
  }
  next();
}

